// Generate CSS custom properties and the style-guide palette from docs/design-tokens/tokens.json.
// Usage: node tools/build_tokens.mjs         (writes the generated files)
//        node tools/build_tokens.mjs --check (exit 1 if any generated file is out of date)
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");

export function loadTokens() {
  return JSON.parse(readFileSync(join(root, "docs/design-tokens/tokens.json"), "utf8"));
}

export function tokensToCss(tokens) {
  const lines = [
    "/* Generated from docs/design-tokens/tokens.json by tools/build_tokens.mjs. Do not edit by hand. */",
    ":root {",
  ];
  for (const [group, entries] of Object.entries(tokens)) {
    if (group.startsWith("$")) continue;
    for (const [name, token] of Object.entries(entries)) {
      const value = Array.isArray(token.$value)
        ? token.$value.map((f) => (/\s/.test(f) ? `"${f}"` : f)).join(", ")
        : token.$value;
      const prefix = group === "size" ? "" : `${group}-`;
      lines.push(`  --${prefix}${name}: ${value};`);
    }
  }
  lines.push("}", "");
  return lines.join("\n");
}

/** WCAG 2.x relative luminance and contrast ratio for #RRGGBB colours. */
export function luminance(hex) {
  const [r, g, b] = [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16) / 255)
    .map((c) => (c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4));
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}
export function contrast(a, b) {
  const [hi, lo] = [luminance(a), luminance(b)].sort((x, y) => y - x);
  return (hi + 0.05) / (lo + 0.05);
}

const escapeHtml = (s) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
const title = (name) => name.split("-").map((w) => w[0].toUpperCase() + w.slice(1)).join(" ");

export function paletteHtml(tokens) {
  const white = tokens.color.curb.$value;
  const ink = tokens.color.asphalt.$value;
  return Object.entries(tokens.color).map(([name, t]) => [
    '        <li class="swatch">',
    `          <span class="swatch-chip" data-color="${name}"></span>`,
    `          <span class="swatch-name">${title(name)}</span>`,
    `          <span><code>${t.$value}</code> <code>--color-${name}</code></span>`,
    `          <span class="swatch-role">${escapeHtml(t.$description)}</span>`,
    `          <span class="swatch-contrast">${contrast(t.$value, white).toFixed(1)}:1 on white, ${contrast(t.$value, ink).toFixed(1)}:1 on asphalt</span>`,
    "        </li>",
  ].join("\n")).join("\n");
}

export function swatchCss(tokens) {
  return Object.keys(tokens.color).map((n) => `.swatch-chip[data-color="${n}"] { background: var(--color-${n}); }`).join("\n");
}

function replaceBlock(text, start, end, body) {
  const i = text.indexOf(start);
  const j = text.indexOf(end);
  if (i < 0 || j < i) throw new Error(`markers ${start} / ${end} not found`);
  return `${text.slice(0, i + start.length)}\n${body}\n${text.slice(j)}`;
}

export function generatedFiles(tokens) {
  const css = tokensToCss(tokens);
  const guide = readFileSync(join(root, "style-guide.html"), "utf8");
  const guideCss = readFileSync(join(root, "assets/css/style-guide.css"), "utf8");
  return {
    "assets/css/tokens.css": css,
    "docs/design-tokens/tokens.css": css,
    "style-guide.html": replaceBlock(guide, "<!-- palette:start -->", "<!-- palette:end -->", paletteHtml(tokens)),
    "assets/css/style-guide.css": replaceBlock(
      guideCss, "/* swatches:start (generated by tools/build_tokens.mjs) */", "/* swatches:end */", swatchCss(tokens),
    ),
  };
}

const isMain = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];
if (isMain) {
  const check = process.argv.includes("--check");
  let stale = false;
  for (const [out, content] of Object.entries(generatedFiles(loadTokens()))) {
    const path = join(root, out);
    let current = "";
    try { current = readFileSync(path, "utf8"); } catch { /* missing counts as stale */ }
    if (current === content) continue;
    if (check) { console.error(`stale: ${out} (run node tools/build_tokens.mjs)`); stale = true; }
    else { writeFileSync(path, content); console.log(`wrote ${out}`); }
  }
  if (stale) process.exit(1);
}
